!function(){"use strict";function documentoLoteCtrl($scope,mS,tS){$scope.tipoDocumentos=[],$scope.lotes=[],$scope.data={},$scope.initialLoad=function(){try{mS.getData("get","/TipoDocumento/Get").then(response=>{var data=JSON.parse(response.data);for(let i=0;i<data.length;i++)null!=data[i].codigoSri&&$scope.tipoDocumentos.push(data[i])})}catch(e){console.log(e)}},$scope.initialLoad(),$scope.get=function(codDoc){try{$scope.lotes=[],mS.getData("get","/DocumentoLote/Get?json="+JSON.stringify({codDoc:codDoc})).then(response=>{"0"!=response.id?"1"!=response.id||($scope.lotes=JSON.parse(response.data)):tS.toastr("warning",response.message)})}catch(e){console.log(e)}},$scope.askToPost=function(){Swal.fire({icon:"warning",title:"Generar Lotes",text:"Esta seguro de generar facturación por lotes para este tipo de documento?",showDenyButton:!0,confirmButtonText:"Si",denyButtonText:"No",allowOutsideClick:!1}).then(result=>{result.value&&$scope.post()})},$scope.post=function(){try{var codDoc=$("#codDoc").val();mS.getData("post","/DocumentoLote/Post?codDoc="+codDoc).then(response=>{if("0"!=response.id)return"1"==response.id?(tS.toastr("success",response.message),$scope.lotes=[],void($scope.lotes=JSON.parse(response.data))):void 0;tS.toastr("warning",response.message)})}catch(error){console.log(error)}},$scope.askToAuthorize=function(item){Swal.fire({icon:"warning",title:"Lote",text:"Esta seguro de enviar al SRI este lote?",showDenyButton:!0,confirmButtonText:"Si",denyButtonText:"No",allowOutsideClick:!1}).then(result=>{result.value&&$scope.authorize(item)})},$scope.authorize=function(item){try{var codDoc=$("#codDoc").val();mS.getData("post","/DocumentoLote/Authorize?idDocumentoLote="+item.idDocumentoLote).then(response=>"AUTORIZADO"!=response.estado?void Swal.fire({icon:"warning",title:response.estado,text:response.message}):void tS.toastr("success",response.message,response.estado))}catch(error){console.log(error)}},$scope.askToDelete=function(item){Swal.fire({icon:"warning",title:"Lote",text:"Esta seguro de eliminar este lote, de manera permanente ?",showDenyButton:!0,confirmButtonText:"Si",denyButtonText:"No",allowOutsideClick:!1}).then(result=>{result.value&&$scope.delete(item)})},$scope.delete=function(item){try{mS.getData("delete","/DocumentoLote/Delete?idDocumentoLote="+item.idDocumentoLote).then(response=>{if("0"!=response.id)return"1"==response.id?(tS.toastr("success",response.message),void $scope.get($scope.data.codDoc)):void 0;tS.toastr("warning",response.message)})}catch(error){console.log(error)}},$scope.documents=[],$scope.getDetails=function(item){try{$scope.documents=[],$scope.loteSelected=item,mS.getData("get","/DocumentoLoteDetalle/Get?idDocumentoLote="+item.idDocumentoLote).then(response=>{if("0"!=response.id)return"1"==response.id?($scope.documents=JSON.parse(response.data),void $("#docsModal").modal("show")):void 0;tS.toastr("warning",response.message)})}catch(error){console.log(error)}},$scope.askToDeleteDoc=function(item){Swal.fire({icon:"warning",title:"Documento",text:"Esta seguro de eliminar este documento del lote, de manera permanente ?",showDenyButton:!0,confirmButtonText:"Si",denyButtonText:"No",allowOutsideClick:!1}).then(result=>{result.value&&$scope.deleteDoc(item)})},$scope.deleteDoc=function(item){try{mS.getData("delete","/DocumentoLoteDetalle/Delete?id="+item.idDocLoteDetalle).then(response=>{if(!1===response)tS.toastr("warning","Error al eliminar el documento");else{tS.toastr("success","Eliminado Exitosamente");let index=$scope.documents.indexOf(item);$scope.documents.splice(index,1);for(const lote of $scope.lotes)if(lote.idDocumentoLote===$scope.loteSelected.idDocumentoLote){lote.cantDocs=$scope.documents.length;break}}})}catch(error){console.log(error)}}}angular.module("acontPlusApp").controller("documentoLoteCtrl",documentoLoteCtrl),documentoLoteCtrl.$inject=["$scope","mainService","toastService"]}(window.angular);